"""Phase 9: docs/evaluation.md is generated by scripts/evaluate.py; these tests keep it honest."""
import re
from datetime import date, time

import pytest

from busbidder.filtering import filter_offers
from busbidder.loader import (load_companies, load_destinations, load_offers, load_scoring_config)
from busbidder.models import TravelRequest
from busbidder.scoring_config import get_config
from scripts.evaluate import SPEC, build_report


@pytest.fixture(scope="module")
def report():
    return build_report()


def test_committed_evaluation_matches_the_script(report):
    # If this fails: run  python scripts/evaluate.py  and commit the new docs/evaluation.md
    assert open("docs/evaluation.md", encoding="utf-8").read() == report


def test_the_experiments_leave_the_scoring_configuration_as_they_found_it(report):
    assert get_config().to_dict() == load_scoring_config().to_dict()


def test_report_has_every_section_and_a_list_of_findings(report):
    for heading in ("## Key findings", "## 1. Are the rankings reasonable?", "## 2. How sensitive is the winner to the weights?",
                    "### 2a.", "### 2b.", "### 2c.", "### 2d.", "## 3. Does one criterion dominate?",
                    "## 4. How sensitive is the result to the numbers", "## 5. Unfair or unreasonable outcomes",
                    "### 5a.", "### 5b.", "### 5c.", "### 5d.", "### 5e.", "### 5f.", "## 6. Reproducibility"):
        assert heading in report, heading
    findings = re.findall(r"^\d+\. .+$", report.split("## 1.")[0], re.M)
    assert len(findings) >= 12 and all(len(f) > 40 for f in findings)


def test_no_experiment_reports_a_warning_or_a_failed_reproducibility_check(report):
    assert "WARNING" not in report and "NO |" not in report
    assert "The ranking is identical in repeated runs and for any input order" in report


def test_fingerprints_are_present_and_look_like_hashes(report):
    assert len(re.findall(r"\| [0-9a-f]{12} \|", report)) >= 7          # 4 rankings + 3 input files


def test_cliff_numbers_agree_with_an_independent_use_of_the_filter(report):
    """The report says OF-0723 (EUR 33.50) is present at budget 33.50 and gone at 33.49. Check with the filter alone."""
    offers = load_offers("data/offers.csv", [d.name for d in load_destinations()],
                         [c.name for c in load_companies()]).offers
    for budget, expected_n, present in ((33.49, 3, False), (33.50, 4, True)):
        kept = filter_offers(offers, TravelRequest(**{**SPEC, "max_budget": budget})).kept
        assert len(kept) == expected_n
        assert any(o.offer_id == "OF-0723" for o in kept) is present
        assert f"| {budget:.2f} | {expected_n} | {'yes' if present else 'no'} |" in report


def test_the_47_offers_of_the_spec_request_agree_with_the_filter(report):
    offers = load_offers("data/offers.csv", [d.name for d in load_destinations()],
                         [c.name for c in load_companies()]).offers
    assert len(filter_offers(offers, TravelRequest(**SPEC)).kept) == 47
    assert "47 offers remain after filtering" in report


def test_night_bus_departure_scores_follow_from_the_scoring_rules(report):
    # at a preferred time of 09:00 a 22:30 departure is 13.5 h (circular: 10.5 h) away, beyond the 6 h tolerance
    assert re.search(r"\| NocheVia \| 0 \| 69 \|", report)
